fx:function(){var pf=ctx.pair(t,s);pf.night=true;pf.nights=(pf.nights||0)+1;st.nights=(st.nights||0)+1;ctx.mod2(t,s,{aff:4,att:6,trust:3},{aff:4,att:6,trust:3});if(!st.pub)st.risk+=4;},
