return{with:[c],text:ctx.t(G.relLead(ctx,a,b)+ctx.pick(T.practice)+G.byPer(ctx,G.CHEER,a),a,b,c),why:a.name+'が、'+b.name+'の'+c.name+'への告白の練習に付き合った（応援・仲良し）',mag:10};
